            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterD = ((aWandererJ + RotL64(aScatter, 48U)) + 0xD9BD9E35CA50B35CULL) + aOASaltG[((aIndex + 8U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aPrevious, 11U)) + 0x5C33042A9CDA4ACAULL) + aOASaltC[((aIndex + 192U)) & S_SALT1];
            aOrbiterG = ((aWandererC + RotL64(aCross, 39U)) + RotL64(aCarry, 21U)) + 0x55101A216BBC6A2AULL;
            aOrbiterF = (aWandererE + RotL64(aIngress, 19U)) + 0x9A1D7D8AE2FCDDC1ULL;
